<?php
namespace App\Domain\AI\Runtime\Data;
final readonly class AgentRuntimeResponseData
{
 public const REASONS=['none','insufficient_knowledge','low_confidence','human_requested','sensitive_action','policy_restriction'];
 public function __construct(public string$answer,public array$citationIds,public string$confidence,public bool$needsHandoff,public string$handoffReason,public array$sources=[]){$answer=trim($answer);if($answer===''||mb_strlen($answer)>1200||preg_match('/[\x00-\x1F\x7F]/u',$answer)||preg_match('~https?://~iu',$answer)||!in_array($confidence,['high','medium','low'],true)||!in_array($handoffReason,self::REASONS,true)||count($citationIds)>10||count($citationIds)!==count(array_unique($citationIds))||(!$needsHandoff&&($citationIds===[]||$handoffReason!=='none'))||($needsHandoff&&$handoffReason==='none')||($confidence==='low'&&!$needsHandoff))throw new \App\Domain\AI\Runtime\Exceptions\InvalidModelResponseException('The structured model response is invalid.');}
 public static function validate(array$data,array$allowed):self{$keys=['answer','citation_ids','confidence','needs_handoff','handoff_reason'];sort($keys);$actual=array_keys($data);sort($actual);if($actual!==$keys||!is_string($data['answer']??null)||!is_array($data['citation_ids']??null)||!is_string($data['confidence']??null)||!is_bool($data['needs_handoff']??null)||!is_string($data['handoff_reason']??null))throw new \App\Domain\AI\Runtime\Exceptions\InvalidModelResponseException('The structured model response is invalid.');foreach($data['citation_ids']as$id)if(!is_string($id)||!in_array($id,$allowed,true))throw new \App\Domain\AI\Runtime\Exceptions\InvalidModelResponseException('The structured model response contains an invalid citation.');return new self(trim($data['answer']),$data['citation_ids'],$data['confidence'],$data['needs_handoff'],$data['handoff_reason']);}
}
